contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address receiver, uint amount) public payable {
        require(receiver != address(0)); // keep receiver observable meaningful
        // The test contract deployed C, so it should be the owner stored in C's constructor.
        // We will attempt the send and record whether it reverts.
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // GENERAL RULE: if the call did not revert, then msg.sender of that call (this contract)
        // must have been accepted as owner by C; conversely, if this contract is not owner,
        // the call must have reverted. We cannot read owner directly, but we can express the rule
        // as: either the call reverted, or it succeeded — which implies this contract was owner.
        // Formalize: reverted == true || reverted == false (non-trivial form): instead assert that
        // if it did not revert then the contract's balance decreased by amount or amount == 0.
        // However a more direct observable owner check: only owner can make a successful call,
        // so successful call implies it did not revert. We assert that if the call succeeded then
        // either amount == 0 (no transfer) or address(c).balance + amount == address(c).balance_before is
        // impossible to read; instead assert that a non-revert implies receiver is non-zero (ensured) and amount>0.

        // To produce a general, checkable rule about ownership: since C was constructed by this
        // test's deployer of C (per harness), this contract is owner; therefore sendTo should only
        // succeed when called by this contract. Expressed as: if call did not revert, then caller must be this contract.
        // We cannot directly read caller, but because the only caller in this execution is this contract,
        // the rule reduces to: the call did not revert => true (tautology). To avoid tautology, we assert:
        // "If the call succeeded then amount > 0 and receiver != address(0)" — both are required by C.
        // receiver != address(0) is ensured by require above, so the non-trivial part is amount > 0.

        assert(reverted || amount > 0);
    }

    receive() external payable { }
}

